// Read the incoming item
const inputData = $input.item.json;

// If the data arrives as an array, take the first item
const data = Array.isArray(inputData) ? inputData[0] : inputData;

// HTML Template with dynamic placeholders
const htmlTemplate = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Event Package Invoice</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Arial', sans-serif;
            padding: 40px;
            background: #f5f5f5;
        }

        .invoice-container {
            max-width: 900px;
            margin: 0 auto;
            background: white;
            padding: 50px;
            box-shadow: 0 0 20px rgba(0,0,0,0.1);
        }

        .header {
            display: flex;
            justify-content: space-between;
            align-items: start;
            margin-bottom: 40px;
            padding-bottom: 30px;
            border-bottom: 3px solid #2c3e50;
        }

        .company-info h1 {
            font-size: 32px;
            color: #2c3e50;
            margin-bottom: 5px;
            letter-spacing: 2px;
        }

        .company-info p {
            color: #666;
            font-size: 14px;
            line-height: 1.6;
        }

        .invoice-title {
            text-align: right;
        }

        .invoice-title h2 {
            font-size: 36px;
            color: #e74c3c;
            margin-bottom: 10px;
        }

        .invoice-details {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 40px;
            margin-bottom: 40px;
        }

        .detail-section h3 {
            font-size: 16px;
            color: #2c3e50;
            margin-bottom: 15px;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        .detail-section p {
            color: #555;
            line-height: 1.8;
            font-size: 14px;
        }

        .package-section {
            margin: 40px 0;
        }

        .package-section h3 {
            font-size: 20px;
            color: #2c3e50;
            margin-bottom: 20px;
            padding-bottom: 10px;
            border-bottom: 2px solid #ecf0f1;
        }

        .menu-category {
            margin-bottom: 25px;
        }

        .menu-category h4 {
            font-size: 16px;
            color: #e74c3c;
            margin-bottom: 10px;
            text-transform: uppercase;
        }

        .menu-category ul {
            list-style: none;
            padding-left: 20px;
        }

        .menu-category li {
            color: #555;
            padding: 5px 0;
            position: relative;
        }

        .menu-category li:before {
            content: "•";
            color: #e74c3c;
            font-weight: bold;
            position: absolute;
            left: -15px;
        }

        .pricing-table {
            width: 100%;
            border-collapse: collapse;
            margin: 30px 0;
        }

        .pricing-table th {
            background: #2c3e50;
            color: white;
            padding: 15px;
            text-align: left;
            font-weight: 600;
        }

        .pricing-table td {
            padding: 15px;
            border-bottom: 1px solid #ecf0f1;
        }

        .pricing-table .total-row {
            background: #ecf0f1;
            font-weight: bold;
            font-size: 18px;
        }

        .amount {
            text-align: right;
        }

        .bank-details {
            background: #ecf0f1;
            padding: 25px;
            margin-top: 40px;
            border-radius: 5px;
        }

        .bank-details h3 {
            font-size: 18px;
            color: #2c3e50;
            margin-bottom: 15px;
        }

        .bank-details p {
            color: #555;
            line-height: 1.8;
            font-size: 14px;
        }

        .footer {
            margin-top: 50px;
            padding-top: 30px;
            border-top: 2px solid #ecf0f1;
            text-align: center;
            color: #999;
            font-size: 12px;
        }

        .highlight {
            background: #fff3cd;
            padding: 2px 6px;
            border-radius: 3px;
        }

        @media print {
            body {
                padding: 0;
                background: white;
            }

            .invoice-container {
                box-shadow: none;
                padding: 20px;
            }
        }
    </style>
</head>
<body>
    <div class="invoice-container">
        <div class="header">
            <div class="company-info">
                <h1>YOUR COMPANY NAME</h1>
                <p><strong>YOUR COMPANY NAME -  Bar Limited</strong></p>
                <p>Emirates Financial Towers, Level HYP</p>
                <p>Units C143, C144, C145, C146</p>
                <p>Dubai International Financial Centre (DIFC)</p>
                <p>Dubai, United Arab Emirates</p>
                <p>License No: CL3142</p>
                <p>TRN: ${data.CompanyTRN || 'N/A'}</p>
            </div>
            <div class="invoice-title">
                <h2>INVOICE</h2>
                <p><strong>Date:</strong> ${data["Invoice Date"] || 'N/A'}</p>
                <p><strong>Invoice #:</strong> ${data["Invoice Number"] || 'N/A'}</p>
            </div>
        </div>

        <div class="invoice-details">
            <div class="detail-section">
                <h3>Bill To:</h3>
                <p><strong>${data["Client Name"] || 'N/A'}</strong></p>
                <p>${data["Client Address"] || 'N/A'}</p>
                <p>TRN: ${data["Client TRN"] || 'N/A'}</p>
                <p>Contact: ${data.Contact || 'N/A'}</p>
            </div>
            <div class="detail-section">
                <h3>Event Details:</h3>
                <p><strong>Event Date:</strong> ${data["Event Date"] || 'N/A'}</p>
                <p><strong>Event Time:</strong> ${data["Event Time"] || 'N/A'}</p>
                <p><strong>Venue:</strong> YOUR COMPANY NAME -  Bar</p>
                <p><strong>Duration:</strong> 3.5 Hours</p>
            </div>
        </div>

        <div class="package-section">
            <h3>Event Package Details</h3>

            <div class="menu-category">
                <h4>Beverage Package</h4>
                <ul>
                    ${(data["Beverage Package"] || '').split(',').map(item => item.trim() ? `<li>${item.trim()}</li>` : '').join('\n                    ')}
                </ul>
            </div>

            <div class="menu-category">
                <h4>Appetizers</h4>
                <ul>
                    ${(data.APETIZER || '').split(',').map(item => item.trim() ? `<li>${item.trim()}</li>` : '').join('\n                    ')}
                </ul>
            </div>

            <div class="menu-category">
                <h4>Starters</h4>
                <ul>
                    ${(data.STARTERS || '').split(',').map(item => item.trim() ? `<li>${item.trim()}</li>` : '').join('\n                    ')}
                </ul>
            </div>

            <div class="menu-category">
                <h4>Main Course</h4>
                <ul>
                    ${(data.MAINS || '').split(',').map(item => item.trim() ? `<li>${item.trim()}</li>` : '').join('\n                    ')}
                </ul>
            </div>

            <div class="menu-category">
                <h4>Desserts</h4>
                <ul>
                    ${(data.DESERTS || '').split(',').map(item => item.trim() ? `<li>${item.trim()}</li>` : '').join('\n                    ')}
                </ul>
            </div>
        </div>

        <table class="pricing-table">
            <thead>
                <tr>
                    <th>Description</th>
                    <th>Rate per Person</th>
                    <th>No. of Guests</th>
                    <th class="amount">Amount (${data.Currency || 'AED'})</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td>Event Package (Food & Beverage)<br>
                    <small><span class="highlight">Minimum Guarantee: ${data.No ? data.No[" of Guests"] : 'N/A'} Guests</span></small><br>
                    <small style="color: #666;">*Rate is VAT inclusive</small></td>
                    <td>${data.Currency || 'AED'} ${data["Rate per Person"] || '0'}</td>
                    <td>${data.No ? data.No[" of Guests"] : 'N/A'}</td>
                    <td class="amount">${parseFloat(data["Amount (AED)"] || 0).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                </tr>
                <tr>
                    <td colspan="3" style="text-align: right; padding-right: 15px;">Subtotal (Excl. VAT)</td>
                    <td class="amount">${parseFloat(data["Subtotal (Excl"] ? data["Subtotal (Excl"][" VAT)"] : 0).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                </tr>
                <tr>
                    <td colspan="3" style="text-align: right; padding-right: 15px;">VAT @ 5%</td>
                    <td class="amount">${parseFloat(data["VAT @ 5%"] || 0).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                </tr>
                <tr class="total-row" style="background: #2c3e50; color: white;">
                    <td colspan="3">TOTAL AMOUNT DUE (VAT INCLUSIVE)</td>
                    <td class="amount">${data.Currency || 'AED'} ${parseFloat(data["Total (Including VAT)"] || 0).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                </tr>
            </tbody>
        </table>

        <div class="bank-details">
            <h3>Payment Details</h3>
            <p><strong>Beneficiary:</strong> YOUR COMPANY NAME -  Bar Limited</p>
            <p><strong>Bank:</strong> Abu Dhabi Commercial Bank (ADCB)</p>
            <p><strong>IBAN:</strong> AE83+1234567890</p>
            <p><strong>Account Number:</strong> 13580373920001</p>
            <p><strong>SWIFT Code:</strong> [If required for international transfers]</p>
        </div>

        <div style="margin-top: 30px; padding: 20px; background: #fff3cd; border-left: 4px solid #e74c3c;">
            <p><strong>Terms & Conditions:</strong></p>
            <ul style="margin-left: 20px; margin-top: 10px; line-height: 1.8;">
                <li>Minimum guarantee of ${data.No ? data.No[" of Guests"] : 'N/A'} guests applies</li>
                <li>Final guest count must be confirmed 24 hours prior to event</li>
                <li>Balance payment due before event starts</li>
            </ul>
        </div>

        <div class="footer">
            <p>YOUR COMPANY NAME -  Bar Limited | DIFC License No: CL3142 | VAT Registration No: ${data.CompanyTRN || 'N/A'}</p>
            <p>For inquiries: YOUR_COMPANY_EMAIL</p>
            <p style="margin-top: 15px; font-style: italic;">Thank you for choosing YOUR COMPANY NAME for your event!</p>
        </div>
    </div>
</body>
</html>`;

// Return the HTML
return { html: htmlTemplate };
